'use strict';
const $=(s,el=document)=>el.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'<path d="M12 5C9 3 5 3 2 4v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1Zm0 0v15"/>',words:'<path d="M4 4h16v16H4zM8 8h8M8 12h6M8 16h4"/>',review:'<path d="M4 8a9 9 0 1 1 0 9M4 3v5h5M12 7v5l3 2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',back:'<path d="m14 5-7 7 7 7M7 12h13"/>',arrow:'<path d="M6 18 18 6M6 6h12v12"/>',next:'<path d="m9 5 7 7-7 7"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',volume:'<path d="m11 4-5 4H2v8h4l5 4V4Zm4 4q5 4 0 8m3-11q8 7 0 14"/>',pause:'<path d="M8 5v14M16 5v14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L20 5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',touch:'<path d="M8 12V6a2 2 0 0 1 4 0v6-3a2 2 0 0 1 4 0v3a2 2 0 0 1 4 0v3q0 6-7 6l-6-6q-2-3 1-3Z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.arrow}</svg>`;
const lessons=window.COURSE;
const byLesson=new Map(lessons.map(l=>[l.id,l]));
const bookWords=lessons.flatMap(l=>l.words.map(w=>({...w,lessonId:l.id,lessonTitle:l.title,source:`课程词表 · p.${w.page}`})));
const wordMap=new Map(bookWords.map(w=>[w.id,w]));
const tokenKeys=new Map();
const wordsByLesson=new Map(lessons.map(l=>[l.id,bookWords.filter(w=>w.lessonId===l.id)]));
for(const l of lessons)for(const [token,g]of Object.entries(l.glosses)){
 const original=wordsByLesson.get(l.id).find(w=>[token,g.lemma?.toLowerCase()].includes(w.word.toLowerCase()));
 const id=original?.id||`gloss-${l.id}-${token}`;
 if(!original)wordMap.set(id,{id,word:g.lemma||token,meaning:g.meaning,notes:[],ipa:'',core:false,lessonId:l.id,lessonTitle:l.title,source:g.note||'课程逐词释义'});
 tokenKeys.set(`${l.id}-${token}`,id);
}
const allWords=[...wordMap.values()];
const STORAGE_KEY='night-reading-public:v1';
let storageAvailable=true,storageWarned=false;
function readSaved(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')||{};}catch{storageAvailable=false;return {};}}
const saved=readSaved();
const validSet=(values,valid)=>new Set(Array.isArray(values)?values.filter(valid):[]);
const state={read:validSet(saved.read,id=>byLesson.has(id)),bookmarks:validSet(saved.bookmarks,id=>byLesson.has(id)),favorites:validSet(saved.favorites,id=>wordMap.has(id)),reviewAdded:validSet(saved.reviewAdded,id=>wordMap.has(id)),last:byLesson.has(saved.last)?saved.last:1,opened:!!saved.opened,accent:['en-GB','en-US'].includes(saved.accent)?saved.accent:'en-GB',slow:!!saved.slow,narrationMode:saved.narrationMode==='natural'&&Object.keys(window.NARRATION.clips).length?'natural':'device',scrolls:saved.scrolls&&typeof saved.scrolls==='object'?saved.scrolls:{},session:null};
if(saved.session&&Array.isArray(saved.session.queue)){const q=saved.session.queue.filter(id=>wordMap.has(id));const i=Number.isInteger(saved.session.index)?Math.max(0,Math.min(saved.session.index,q.length)):0;if(q.length)state.session={queue:q,index:i,revealed:!!saved.session.revealed,known:Number(saved.session.known)||0,again:Number(saved.session.again)||0};}
const ui={themeOpen:new Set(),bookSearch:'',bookRange:0,wordSearch:'',wordFilter:'全部',wordLesson:0,wordLimit:24,bookFilter:'全部',reviewLesson:state.last,sheet:null,lastTrigger:null,quizAnswer:'',quizResult:null};
let currentRoute=null,toastTimer=null,scrollTimer=null,speech=null;
function snapshot(){return {version:1,read:[...state.read],bookmarks:[...state.bookmarks],favorites:[...state.favorites],reviewAdded:[...state.reviewAdded],last:state.last,opened:state.opened,accent:state.accent,slow:state.slow,narrationMode:state.narrationMode,scrolls:state.scrolls,session:state.session};}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(snapshot()));storageAvailable=true;}catch{storageAvailable=false;if(!storageWarned){storageWarned=true;toast('浏览器暂时无法保存记录，可以在“我的”中导出。');}}}
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},3200);}
function route(){const parts=location.hash.slice(1).split('/');const name=parts[0]||'home';const id=Number(parts[1]);if(['sentence','exercise','done'].includes(name)&&byLesson.has(id))return {name,id,key:`${name}/${id}`};if(['home','words','review','reviewdone','me','about'].includes(name))return {name,key:name};return {name:'home',key:'home'};}
function rememberScroll(){if(currentRoute)state.scrolls[currentRoute.key]=$('#main').scrollTop;}
function navigate(key){rememberScroll();stopAudio();closeSheet(false);ui.quizAnswer='';ui.quizResult=null;persist();if(location.hash.slice(1)===key)render(false,true);else location.hash=key;}
function button(label,action,kind='primary',attrs=''){return `<button type="button" class="button ${kind}" data-action="${action}" ${attrs}>${label}</button>`;}
function backbar(label,action='home',extra=''){return `<div class="backbar"><button class="icon-button" data-action="${action}" aria-label="返回">${icon('back')}</button><span>${label}</span>${extra||'<span style="width:44px"></span>'}</div>`;}
function home(){const l=byLesson.get(state.last);return `<div class="topbar"><div class="brand">100句<small>READ AT YOUR OWN PACE</small></div><span class="edition">${lessons.length}句示例</span></div><div class="greeting"><p class="eyebrow">YOUR QUIET ENGLISH SPACE</p><h1 class="page-title">安静下来，进入英语。</h1><p class="subcopy">跟着自己的节奏，读懂这100句话。</p></div><div class="progress-label"><span>已读懂 <b>${state.read.size}</b> 句</span><span>共 ${lessons.length} 句</span></div><div class="progress-track" role="progressbar" aria-label="累计阅读进度" aria-valuemin="0" aria-valuemax="${lessons.length}" aria-valuenow="${state.read.size}"><span style="width:${state.read.size/lessons.length*100}%"></span></div><section class="resume-card"><span class="lettering" aria-hidden="true">Aa</span><div class="resume-meta"><p class="eyebrow">${state.opened?'上次读到':'从这里开始'}</p><span class="badge">第 ${String(l.id).padStart(2,'0')} 句</span></div><h2>${esc(l.title)}</h2><p class="resume-sentence">${esc(l.sentence.slice(0,90))}…</p>${button(`${state.read.has(l.id)?'再读一遍':state.opened?'接着读':'开始读'} ${icon('arrow')}`,'open-lesson','primary',`data-id="${l.id}"`)}</section><div class="section-heading"><h2>句子目录</h2><span class="quiet">自由选读</span></div><label class="search-wrap" style="display:block">${icon('search')}<span class="screen-reader-only">搜索句子或主题</span><input class="search-input" id="book-search" data-input="book-search" placeholder="搜索句子、主题或序号" value="${esc(ui.bookSearch)}" autocomplete="off"></label><label class="lesson-select-row"><span>阅读范围</span><select id="book-range" aria-label="阅读范围"><option value="0">全部示例句</option>${Array.from({length:Math.ceil(lessons.length/10)},(_,i)=>`<option value="${i+1}" ${ui.bookRange===i+1?'selected':''}>第 ${String(i*10+1).padStart(2,'0')}–${Math.min((i+1)*10,lessons.length)} 句</option>`).join('')}</select></label><div class="filter-row" role="group" aria-label="句子筛选">${['全部','已读懂','收藏'].map(f=>`<button data-action="book-filter" data-value="${f}" class="${ui.bookFilter===f?'active':''}" aria-pressed="${ui.bookFilter===f}">${f}</button>`).join('')}</div>${lessons.filter(l=>(!ui.bookRange||Math.floor((l.id-1)/10)===ui.bookRange-1)&&(!ui.bookSearch||`${l.id} ${l.title} ${l.sentence} ${l.translation}`.toLowerCase().includes(ui.bookSearch.toLowerCase()))&&(ui.bookFilter!=='已读懂'||state.read.has(l.id))&&(ui.bookFilter!=='收藏'||state.bookmarks.has(l.id))).map(l=>`<button class="book-row ${state.read.has(l.id)?'read':''}" data-action="open-lesson" data-id="${l.id}"><span class="number">${String(l.id).padStart(2,'0')}</span><span><strong>${esc(l.title)}</strong><small>${state.read.has(l.id)?'✓ 已读懂':state.opened&&state.last===l.id?'上次读到这里':`${l.words.filter(w=>w.core).length} 个核心词`}</small></span><span class="row-icon">${icon('arrow')}</span></button>`).join('')||'<div class="empty">这里暂时没有句子。<br>可以切换到“全部”，选一句读读。</div>'}<p class="sample-note">${icon('info')}<span>这里展示原创示例内容。读到喜欢的地方，随时可以停下来。</span></p>`;}
function sentenceMarkup(l){let tokenIndex=0;return l.sentence.split(/([a-zA-Z]+(?:'[a-zA-Z]+)?)/).map(w=>/^[a-zA-Z]/.test(w)?`<button class="sentence-word ${wordMap.get(tokenKeys.get(`${l.id}-${w.toLowerCase()}`))?.core?'core':''}" data-action="word" data-token-index="${tokenIndex++}" data-key="${esc(tokenKeys.get(`${l.id}-${w.toLowerCase()}`)||'')}" aria-label="查看 ${esc(w)} 的释义">${esc(w)}</button>`:esc(w)).join('');}
function audioButton(text,lang=state.accent,label='听原句'){const active=speech?.text===text&&speech?.lang===lang;const loading=active&&speech.loading;return `<button class="audio-button ${active?'active':''} ${loading?'loading':''}" data-action="speak" data-label="${esc(label)}" data-text="${esc(text)}" data-lang="${lang}" aria-label="${loading?'取消加载':active&&!speech.paused?'暂停朗读':active?'继续朗读':label}" aria-busy="${!!loading}">${icon(active&&!speech.paused&&!loading?'pause':'volume')}${loading?'准备声音…':active?(speech.paused?'继续':'暂停'):label}</button>`;}
function coreWordTable(l){const words=l.words.filter(w=>w.core);return `<section class="core-vocabulary" aria-labelledby="core-heading"><div class="section-heading"><h2 id="core-heading">核心词表</h2><span class="quiet">${words.length} 个词条</span></div><p class="core-intro">按课程顺序 · 点词查看搭配与记忆</p><ul class="core-word-list">${words.map((w,i)=>`<li class="core-word-card"><div class="core-word-top"><span class="core-word-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><button class="core-word-detail" data-action="word" data-key="${esc(w.id)}" aria-label="查看 ${esc(w.word)} 的词条详情"><strong>${esc(w.word)}</strong>${w.ipa?`<span class="ipa">${esc(w.ipa)}</span>`:''}<span class="core-word-meaning">${esc(w.meaning)}</span><span class="core-detail-link">${w.notes.length?'搭配与记忆':'查看词条'} ${icon('next')}</span></button></div><div class="core-word-footer"><span class="source-label">课程 p.${w.page}</span>${audioButton(w.word,state.accent,'听发音')}</div></li>`).join('')}</ul></section>`;}
function thematicVocabulary(l){const groups=new Map();for(const w of l.words.filter(w=>!w.core)){if(!groups.has(w.group))groups.set(w.group,[]);groups.get(w.group).push(w);}if(!groups.size)return '';return `<section class="theme-vocabulary" aria-labelledby="theme-heading"><div class="section-heading"><h2 id="theme-heading">主题归纳</h2><span class="quiet">${groups.size} 个主题 · ${l.words.filter(w=>!w.core).length} 个词条</span></div><p class="core-intro">顺着这句话，认识更多相关的词。选一个主题展开看看。</p>${[...groups].map(([name,words],i)=>{const key=`${l.id}-${i}`,open=ui.themeOpen.has(key);return `<div class="theme-group"><h3><button class="theme-toggle" data-action="theme-group" data-key="${key}" aria-expanded="${open}" aria-controls="theme-${key}"><span>${esc(name)}<small>${words.length} 个词条 · 课程 p.${words[0].page}–${words.at(-1).page}</small></span><span class="theme-toggle-symbol" aria-hidden="true">${open?'−':'＋'}</span></button></h3><ul id="theme-${key}" class="theme-word-list" ${open?'':'hidden'}>${open?words.map(w=>`<li class="theme-word-row"><button class="theme-word-detail" data-action="word" data-key="${esc(w.id)}" aria-label="查看 ${esc(w.word)} 的词条详情"><strong>${esc(w.word)}</strong>${w.ipa?`<span class="ipa">${esc(w.ipa)}</span>`:''}<span class="core-word-meaning">${esc(w.meaning)}</span><span class="core-detail-link">查看词条 ${icon('next')}</span></button>${audioButton(w.word,state.accent,'听发音')}</li>`).join(''):''}</ul></div>`;}).join('')}</section>`;}
function sentence(l){const bookmarked=state.bookmarks.has(l.id);return `${backbar(`句子精读 / ${String(l.id).padStart(2,'0')}`,'home',`<button class="icon-button ${bookmarked?'selected':''}" data-action="bookmark" data-id="${l.id}" aria-label="${bookmarked?'取消收藏句子':'收藏句子'}" aria-pressed="${bookmarked}">${icon('star')}</button>`)}<div class="lesson-heading"><p class="eyebrow">LOOK BEYOND THE WORDS</p><h1 class="page-title">${esc(l.title)}</h1><div class="metadata"><span class="chip">第 ${String(l.id).padStart(2,'0')} 句</span><span class="source-label">${l.words.filter(w=>w.core).length} 个核心词 · 课程 p.${l.startPage}</span></div></div><div class="sentence" aria-label="英文原句">${sentenceMarkup(l)}</div><div class="lookup-hint">${icon('touch')}<span>点任意单词，查看它在这里的意思</span></div><div class="audio-row">${audioButton(l.sentence)}<button class="audio-button" data-action="accent">${state.accent==='en-GB'?'英音 UK':'美音 US'} ⇄</button><button class="audio-button" data-action="slow" aria-pressed="${state.slow}">${state.slow?'慢速':'自然语速'}</button></div><p class="audio-caption">${state.narrationMode==='natural'?`自然朗读 · ${state.accent==='en-GB'?'Sonia 英音':'Ava 美音'}`:'设备朗读'} · ${state.slow?'清晰慢速':'自然语速'}</p><section class="disclosure"><button data-action="translation" aria-expanded="${ui.translation===l.id}"><span>中文释义</span><span>${ui.translation===l.id?'收起 −':'展开 +'}</span></button>${ui.translation===l.id?`<p class="translation">${esc(l.translation)}</p>`:''}</section><section class="disclosure"><button data-action="grammar" aria-expanded="${ui.grammar===l.id}"><span>读懂句子结构</span><span>${ui.grammar===l.id?'收起 −':'展开 +'}</span></button>${ui.grammar===l.id?`<p class="grammar">${esc(l.grammar)}</p>`:''}</section>${coreWordTable(l)}${thematicVocabulary(l)}<button class="optional-link" data-action="exercise" data-id="${l.id}"><span>想试试？回忆这句话</span>${icon('next')}</button><div class="lesson-switch"><button data-action="open-lesson" data-id="${l.id-1}" ${l.id===1?'disabled':''}>← 上一句</button><button data-action="${l.id===lessons.length?'home':'open-lesson'}" data-id="${l.id+1}">${l.id===lessons.length?'回到目录':'下一句 →'}</button></div>`;}
function lessonSelect(id,value,label){return `<label class="lesson-select-row"><span>${label}</span><select id="${id}" aria-label="${label}"><option value="0" ${value===0?'selected':''}>全部示例句</option>${lessons.map(l=>`<option value="${l.id}" ${value===l.id?'selected':''}>第 ${String(l.id).padStart(2,'0')} 句 · ${esc(l.title)}</option>`).join('')}</select></label>`;}
function vocabulary(){const rows=allWords.filter(w=>(ui.wordFilter!=='核心'||w.core)&&(ui.wordFilter!=='收藏'||state.favorites.has(w.id))&&(!ui.wordLesson||w.lessonId===ui.wordLesson)&&(!ui.wordSearch||`${w.word} ${w.meaning}`.toLowerCase().includes(ui.wordSearch.toLowerCase())));return `<p class="eyebrow">WORDS IN CONTEXT</p><h1 class="page-title">在句子里，<br>重新遇见单词。</h1><p class="subcopy">随时查一查，收藏想留下的词。</p><label class="search-wrap" style="display:block">${icon('search')}<span class="screen-reader-only">搜索单词或中文释义</span><input class="search-input" id="word-search" data-input="word-search" placeholder="搜索单词或中文释义" value="${esc(ui.wordSearch)}" autocomplete="off"></label><div class="filter-row" role="group" aria-label="词库筛选">${['全部','核心','收藏'].map(f=>`<button data-action="word-filter" data-value="${f}" class="${ui.wordFilter===f?'active':''}" aria-pressed="${ui.wordFilter===f}">${f}</button>`).join('')}</div>${lessonSelect('word-lesson-select',ui.wordLesson,'来源句子')}<p class="quiet">${rows.length} 个词条 · 来自当前示例课程</p>${rows.slice(0,ui.wordLimit).map(w=>`<button class="word-row" data-action="word" data-key="${esc(w.id)}"><span><strong>${esc(w.word)}</strong><span class="definition">${esc(w.meaning)}</span><span class="origin">第 ${String(w.lessonId).padStart(2,'0')} 句 · ${esc(w.lessonTitle)}</span></span><span class="row-icon">${icon(state.favorites.has(w.id)?'star':'arrow')}</span></button>`).join('')||'<div class="empty">这里还没有匹配的词。<br>可以换个词搜索，或切换筛选。</div>'}${rows.length>ui.wordLimit?button('再看看更多词条','more-words','secondary load-more'):''}`;}
function reviewPool(){const selected=[...state.reviewAdded].map(id=>wordMap.get(id)).filter(Boolean);const core=bookWords.filter(w=>w.core);return [...new Map([...selected,...core].filter(w=>!ui.reviewLesson||w.lessonId===ui.reviewLesson).map(w=>[w.id,w])).values()];}
function review(){const session=state.session;if(session&&session.index<session.queue.length){const w=wordMap.get(session.queue[session.index]);return `${backbar(`词汇回顾 · ${session.index+1} / ${session.queue.length}`,'pause-review')}<div class="recall-progress"><span class="active" style="flex:0 0 ${(session.index+1)/session.queue.length*100}%"></span></div><p class="recall-instruction">${session.revealed?'看看释义，想想它在句子里的样子。':'这个词是什么意思？试着回忆一下。'}</p><div class="flashcard"><p class="eyebrow">第 ${String(w.lessonId).padStart(2,'0')} 句 · ${w.core?'核心词汇':'留给回顾的词'}</p><h2>${esc(w.word)}</h2>${w.ipa?`<span class="ipa">${esc(w.ipa)}</span>`:''}${audioButton(w.word,state.accent,state.accent==='en-GB'?'英音':'美音')}${session.revealed?`<p class="definition">${esc(w.meaning)}</p><p class="context">${esc(byLesson.get(w.lessonId).sentence)}</p>`:''}</div><p class="recall-instruction">想不起来也没关系，随时可以再看。</p><div class="recall-actions">${session.revealed?`${button('想再看看','rate','secondary','data-value="again"')}${button('有印象了','rate','primary','data-value="known"')}`:button('看看答案','reveal')}</div><button class="text-button" data-action="pause-review">先看到这里，稍后继续</button>`;}
 const count=reviewPool().length;return `<p class="eyebrow">RETURN TO WHAT YOU READ</p><h1 class="page-title">回到熟悉的句子。</h1><p class="subcopy">读过的句子、见过的词，<br>想再看看时，随时回来。</p><section class="review-intro"><h2>回想几个词</h2><p class="subcopy">先想一想，或直接翻开答案。<br>忘记也没关系，随时可以停下来。</p>${lessonSelect('review-lesson-select',ui.reviewLesson,'回顾来源')}<p class="quiet">${count} 个词 · 核心词与自己留下的词</p>${button('看看这些词 →','start-review','primary',count?'':'disabled')}</section>${button('再读一句','resume','secondary load-more')}<p class="review-footer-note">想再看看时，就来这里。</p>`;}
function finish(id,isReview=false){const allDone=state.read.size===lessons.length;const session=state.session;return `<div class="finish-view"><p class="eyebrow">AT YOUR OWN PACE</p><div class="success-symbol">${icon('check')}</div><h1>${isReview?'这次，就看到这里。':allDone?'这些句子，读懂了。':'这一句，读懂了。'}</h1><p class="subcopy">${isReview?'看过的词，慢慢会熟悉。<br>下次想起时，再回来看看。':'它已经留在你的阅读记录里。<br>接着读，或先停在这里，都可以。'}</p><div class="finish-stat">${isReview?`${session?.known||0}<small> 个词</small><span>这次有印象了</span>`:`${state.read.size}<small> / ${lessons.length} 句</small><span>累计已读懂</span>`}</div>${isReview?button('回到100句','home'):id<lessons.length?button('想接着读下一句 →','open-lesson','primary',`data-id="${id+1}"`):button('回到目录','home')}${button(isReview?'再回顾一遍':'先读到这里，回到目录',isReview?'review-again':'home','secondary')}${!isReview?`<button class="text-button" data-action="open-lesson" data-id="${id}">再读一遍这句话</button>`:''}${allDone&&!isReview?'<p class="review-footer-note">这些示例句都读过了。<br>可以在词库和回顾里，再遇见它们。</p>':''}</div>`;}
function me(){return `<p class="eyebrow">YOUR READING SPACE</p><h1 class="page-title">按自己的节奏。</h1><p class="subcopy">每一个读懂的句子，都会留在这里。</p><div class="settings-metric"><strong>${state.read.size}<small> / ${lessons.length} 句</small></strong><span>累计已读懂 · 全部示例句已开放</span></div><div class="section-heading"><h2>阅读偏好</h2></div><label class="settings-row"><span>朗读声音</span><select aria-label="朗读声音" id="narration-select"><option value="natural" ${state.narrationMode==='natural'?'selected':''}>自然朗读（需自备音频）</option><option value="device" ${state.narrationMode==='device'?'selected':''}>设备朗读</option></select></label><label class="settings-row"><span>默认口音</span><select aria-label="默认口音" id="accent-select"><option value="en-GB" ${state.accent==='en-GB'?'selected':''}>英国英语</option><option value="en-US" ${state.accent==='en-US'?'selected':''}>美国英语</option></select></label><button class="settings-row" data-action="speak" data-text="A little progress, at your own pace." data-lang="${state.accent}"><span>试听发音</span><span>${icon('volume')}</span></button><div class="settings-row"><span>收藏的词</span><span>${state.favorites.size} 个</span></div><button class="settings-row" data-action="export"><span>导出阅读记录</span><span>${icon('download')}</span></button><button class="settings-row" data-route="about"><span>内容与使用声明</span><span>${icon('next')}</span></button><div class="settings-note"><b>${storageAvailable?'记录已保存在这台设备':'当前浏览器暂时无法保存'}</b>${storageAvailable?'关闭或刷新后，可以接着读。清除浏览器数据或更换设备时，记录不会自动转移；可以先导出备份。':'请先导出阅读记录，避免关闭页面后丢失。'}</div>`;}
function about(){return `${backbar('内容与使用声明','me')}<h1 class="page-title">学习与交流。</h1><ul class="note-list"><li>本公开版仅面向英语学习与前端开发爱好者，使用原创示例句与自编释义，不包含商业书籍、原书音频或词典数据库。</li><li>源码公开供非商业学习、研究和交流，禁止商业化及任何侵权、违法用途。详见 <a href="LICENSE.txt" target="_blank" rel="noopener">非商业使用许可</a>。</li><li>项目按现状提供，不保证内容、发音、功能的准确性、完整性或适用性，不保证考试成绩或学习效果。用户应自行核验并承担依法应负的使用责任。</li><li>在适用法律允许的范围内，作者与维护者不承担因使用或无法使用本项目导致的损失；不排除法律明确规定不得排除或限制的责任。</li><li>自行导入的文本、图片、词典和音频须取得相应权利人的许可。免责声明不构成第三方内容授权，也不能免除依法应承担的责任。</li><li>阅读位置、收藏和回顾记录仅保存在当前浏览器。设备朗读依赖浏览器声音，自备自然音频仅可在有权使用的范围内使用。</li></ul><p class="subcopy">请阅读 <a href="DISCLAIMER.html" target="_blank" rel="noopener">完整免责声明</a>。</p>`;}

function exercise(l){return `${backbar('随手练一句','return-sentence')}<p class="eyebrow">ONE SMALL CHECK</p><h1 class="page-title">把单词，放回句子里。</h1><p class="subcopy">想试试就试试，随时可以回到原句。</p><p class="sentence">${esc(l.sentence.replace(l.exerciseAnswer,'______'))}</p><label for="quiz-answer" class="quiz-label">YOUR ANSWER</label><input id="quiz-answer" class="quiz-input" data-input="quiz" placeholder="输入缺失的单词" autocomplete="off" autocapitalize="none" spellcheck="false" value="${esc(ui.quizAnswer)}"><p class="quiz-feedback" role="status">${ui.quizResult==='correct'?'✓ 答对了，它已经和语境连起来了。':ui.quizResult==='wrong'?'再看看原句，也许就想起来了。':ui.quizResult==='hint'?`首字母是 ${esc(l.exerciseAnswer[0])}，共 ${l.exerciseAnswer.length} 个字母。`:''}</p>${button(ui.quizResult==='correct'?'回到原句':'看看答案对不对',ui.quizResult==='correct'?'return-sentence':'check-answer','primary',ui.quizAnswer.trim()?'':'disabled')}<button class="text-button" data-action="quiz-hint">想看一点提示？</button>`;}
function paintNav(active){$('#navigation').innerHTML=active?`<div class="bottom-nav">${[['home','book','100句'],['words','words','词库'],['review','review','回顾'],['me','user','我的']].map(([r,i,label])=>`<button class="nav-button ${active===r?'active':''}" data-route="${r}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</div>`:'';}
function render(keepScroll=true,focus=false){const main=$('#main');const oldTop=main.scrollTop;rememberScroll();const r=route();currentRoute=r;if(r.name==='sentence'){state.last=r.id;state.opened=true;ui.reviewLesson=r.id;}
 const html={home,words:vocabulary,review,reviewdone:()=>finish(0,true),me,about,sentence:()=>sentence(byLesson.get(r.id)),exercise:()=>exercise(byLesson.get(r.id)),done:()=>finish(r.id)}[r.name]();main.innerHTML=html;
 $('#actions').innerHTML=r.name==='sentence'?`<div class="lesson-bottom">${button(`${state.read.has(r.id)?'已经读懂，再记一次':'标记为已读懂'} ${icon('check')}`,'mark-read',state.read.has(r.id)?'already':'primary',`data-id="${r.id}"`)}</div>`:'';
 paintNav(['home','words','review','me'].includes(r.name)?r.name:null);
 main.scrollTop=keepScroll?oldTop:Number(state.scrolls[r.key])||0;
 if(focus)main.focus({preventScroll:true});persist();
}
function paintSheet(){const w=ui.sheet;if(!w){$('#overlay').innerHTML='';return;}const favorite=state.favorites.has(w.id),added=state.reviewAdded.has(w.id);$('#overlay').innerHTML=`<div class="sheet-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(w.word)} 词义"><div class="sheet-handle"></div><div class="sheet-top"><p class="eyebrow">IN THIS SENTENCE</p><button class="icon-button" data-action="close-sheet" aria-label="关闭词义">${icon('close')}</button></div><h2>${esc(w.word)}</h2>${w.ipa?`<span class="ipa">${esc(w.ipa)}</span>`:''}<div class="audio-row">${audioButton(w.word,'en-GB','英音')}${audioButton(w.word,'en-US','美音')}</div><p class="definition">${esc(w.meaning)}</p>${w.notes?.length?`<div class="memory-note"><b>理解与记忆</b>${w.notes.map(note=>`<p>${esc(note)}</p>`).join('')}</div>`:''}<span class="source-label">第 ${String(w.lessonId).padStart(2,'0')} 句 · ${esc(w.lessonTitle)}<br>${esc(w.source)}</span><div class="sheet-buttons">${button(`${favorite?'已收藏':'收藏这个词'} ${icon('star')}`,'favorite','secondary',`aria-pressed="${favorite}"`)}${button(added?'已加入回顾 ✓':'＋ 加入回顾','add-review','primary',`aria-pressed="${added}"`)}</div></section></div>`;}
function openSheet(key,trigger){const w=wordMap.get(key);if(!w)return;ui.sheet=w;ui.lastTrigger=trigger;$('.app-shell').inert=true;paintSheet();$('.sheet [data-action="close-sheet"]').focus({preventScroll:true});}
function closeSheet(refresh=true){if(!ui.sheet)return;stopAudio();const trigger=ui.lastTrigger;const key=ui.sheet.id;ui.sheet=null;ui.lastTrigger=null;$('.app-shell').inert=false;$('#overlay').innerHTML='';if(refresh){render(true);const target=trigger?.isConnected?trigger:document.querySelector(`button[data-action="word"][data-key="${CSS.escape(key)}"]`);target?.focus({preventScroll:true});}}
let narrator;
function stopAudio(){narrator?.stop();}
function refreshAudio(){
 document.querySelectorAll('.audio-button[data-action="speak"]').forEach(b=>{
  const active=speech?.text===b.dataset.text&&speech?.lang===b.dataset.lang;
  const loading=active&&speech.loading;const label=b.dataset.label||'听发音';
  b.classList.toggle('active',!!active);b.classList.toggle('loading',!!loading);
  b.setAttribute('aria-busy',String(!!loading));
  b.setAttribute('aria-label',loading?'取消加载':active&&!speech.paused?'暂停朗读':active?'继续朗读':label);
  b.innerHTML=`${icon(active&&!speech.paused&&!loading?'pause':'volume')}${loading?'准备声音…':active?(speech.paused?'继续':'暂停'):esc(label)}`;
 });
 const sample=document.querySelector('.settings-row[data-action="speak"]');
 if(sample)sample.setAttribute('aria-busy',String(!!speech?.loading));
}
function speak(text,lang){narrator.play(text,lang,{slow:state.slow,mode:state.narrationMode});}
function highlightWord(progress){document.querySelectorAll('.sentence-word.speaking').forEach(n=>n.classList.remove('speaking'));const r=route();if(!progress||r.name!=='sentence'||byLesson.get(r.id).sentence!==progress.text)return;document.querySelector(`.sentence-word[data-token-index="${progress.index}"]`)?.classList.add('speaking');}
narrator=new window.Narrator({onState:value=>{speech=value;if(currentRoute?.key===route().key)refreshAudio();},onWord:highlightWord,onError:toast});

document.addEventListener('click',e=>{
 if(e.target.matches('.sheet-backdrop')){closeSheet();return;}
 const b=e.target.closest('button[data-action],button[data-route]');if(!b||b.disabled)return;if(b.dataset.route){navigate(b.dataset.route);return;}
 const a=b.dataset.action,r=route(),id=Number(b.dataset.id);
 switch(a){
 case'home':navigate('home');return;case'me':navigate('me');return;
 case'open-lesson':if(byLesson.has(id))navigate(`sentence/${id}`);return;
 case'resume':navigate(`sentence/${state.last}`);return;
 case'bookmark':state.bookmarks.has(id)?state.bookmarks.delete(id):state.bookmarks.add(id);persist();render(true);toast(state.bookmarks.has(id)?'这句话已收藏。':'已取消收藏。');return;
 case'book-filter':ui.bookFilter=b.dataset.value;render(true);return;
 case'theme-group':{const key=b.dataset.key;ui.themeOpen.has(key)?ui.themeOpen.delete(key):ui.themeOpen.add(key);render(true);document.querySelector(`[data-action="theme-group"][data-key="${CSS.escape(key)}"]`)?.focus({preventScroll:true});return;}
 case'word':openSheet(b.dataset.key,b);return;
 case'close-sheet':closeSheet();return;
 case'favorite':{const key=ui.sheet.id;state.favorites.has(key)?state.favorites.delete(key):state.favorites.add(key);persist();const selected=state.favorites.has(key);b.setAttribute('aria-pressed',String(selected));b.innerHTML=`${selected?'已收藏':'收藏这个词'} ${icon('star')}`;return;}
 case'add-review':{const key=ui.sheet.id;state.reviewAdded.has(key)?state.reviewAdded.delete(key):state.reviewAdded.add(key);persist();const selected=state.reviewAdded.has(key);b.setAttribute('aria-pressed',String(selected));b.textContent=selected?'已加入回顾 ✓':'＋ 加入回顾';toast(state.reviewAdded.has(key)?'已经留下，想回顾时随时回来。':'已从回顾中移除。');return;}
 case'speak':speak(b.dataset.text,b.dataset.lang);return;
 case'accent':stopAudio();state.accent=state.accent==='en-GB'?'en-US':'en-GB';persist();render(true);return;
 case'slow':stopAudio();state.slow=!state.slow;persist();render(true);return;
 case'translation':ui.translation=ui.translation===r.id?null:r.id;render(true);return;
 case'grammar':ui.grammar=ui.grammar===r.id?null:r.id;render(true);return;
 case'mark-read':state.read.add(id);persist();navigate(`done/${id}`);return;
 case'exercise':navigate(`exercise/${id}`);return;
 case'return-sentence':navigate(`sentence/${r.id}`);return;
 case'check-answer':ui.quizResult=ui.quizAnswer.trim().toLowerCase()===byLesson.get(r.id).exerciseAnswer.toLowerCase()?'correct':'wrong';render(true);return;
 case'quiz-hint':ui.quizResult='hint';render(true);return;
 case'word-filter':ui.wordFilter=b.dataset.value;ui.wordLimit=24;render(false);return;
 case'word-lesson':ui.wordLesson=id;ui.wordLimit=24;render(false);return;
 case'more-words':ui.wordLimit+=24;render(true);return;
 case'review-lesson':ui.reviewLesson=id;render(true);return;
 case'start-review':{const q=reviewPool().map(w=>w.id);if(!q.length)return;state.session={queue:q,index:0,revealed:false,known:0,again:0};persist();render(false,true);return;}
 case'reveal':state.session.revealed=true;persist();render(true);return;
 case'rate':{const s=state.session;if(!s||!s.revealed)return;if(b.dataset.value==='known'){s.known++;state.reviewAdded.delete(s.queue[s.index]);}else{s.again++;state.reviewAdded.add(s.queue[s.index]);}s.index++;s.revealed=false;persist();stopAudio();if(s.index===s.queue.length)navigate('reviewdone');else{state.scrolls.review=0;render(false,true);}return;}
 case'pause-review':persist();navigate('home');toast('位置已留下，下次可以接着看。');return;
 case'review-again':state.session=null;persist();navigate('review');return;
 case'export':{const blob=new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='100ju-night-reading.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('阅读记录已导出。');return;}
 }
});
document.addEventListener('input',e=>{if(e.target.dataset.input==='book-search'){const pos=e.target.selectionStart;ui.bookSearch=e.target.value;render(true);const input=$('#book-search');input.focus({preventScroll:true});input.setSelectionRange(pos,pos);}if(e.target.dataset.input==='word-search'){const pos=e.target.selectionStart;ui.wordSearch=e.target.value;ui.wordLimit=24;render(true);const input=$('#word-search');input.focus({preventScroll:true});input.setSelectionRange(pos,pos);}if(e.target.dataset.input==='quiz'){ui.quizAnswer=e.target.value;ui.quizResult=null;const btn=$('[data-action="check-answer"],[data-action="return-sentence"].primary');if(btn){btn.disabled=!ui.quizAnswer.trim();btn.dataset.action='check-answer';btn.textContent='看看答案对不对';}$('.quiz-feedback').textContent='';}});
document.addEventListener('change',e=>{if(e.target.id==='book-range'){ui.bookRange=Number(e.target.value);render(true);}if(e.target.id==='word-lesson-select'){ui.wordLesson=Number(e.target.value);ui.wordLimit=24;render(true);}if(e.target.id==='review-lesson-select'){ui.reviewLesson=Number(e.target.value);render(true);}if(e.target.id==='narration-select'){stopAudio();state.narrationMode=e.target.value==='device'?'device':'natural';persist();render(true);}if(e.target.id==='accent-select'){stopAudio();state.accent=e.target.value;persist();render(true);}});
document.addEventListener('keydown',e=>{if(ui.sheet){if(e.key==='Escape'){closeSheet();return;}if(e.key==='Tab'){const items=[...$('.sheet').querySelectorAll('button')].filter(b=>!b.disabled);if(e.shiftKey&&document.activeElement===items[0]){items.at(-1).focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){items[0].focus();e.preventDefault();}}}if(e.key==='Enter'&&e.target.id==='quiz-answer')$('[data-action="check-answer"]')?.click();});
$('#main').addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{rememberScroll();persist();},250);},{passive:true});
window.addEventListener('hashchange',()=>{stopAudio();closeSheet(false);render(false,true);});
window.addEventListener('pagehide',()=>{rememberScroll();persist();stopAudio();});
render(false);
